export const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={overview:'M3 3h7v7H3zm11 0h7v7h-7zM3 14h7v7H3zm11 0h7v7h-7z',training:'M4 8v8m3-10v12m10-12v12m3-10v8M7 12h10',exercises:'M4 4h16v16H4zM8 8h8M8 12h8M8 16h4',anatomy:'M12 3a2 2 0 1 0 0 4a2 2 0 1 0 0-4M5 10l7-2l7 2M12 8v6m0 0l-4 7m4-7l4 7',body:'M5 5h14v16H5zM9 5V3h6v2m-6 5h6',calories:'M8 3h8v4l4 5v9H4v-9l4-5V3m0 4h8M8 15h8',cardio:'M3 12h4l3-7l4 14l3-7h4',plan:'M4 5h16v16H4zM8 3v4m8-4v4M4 10h16M8 14h2m4 0h2',insights:'M4 20V10m8 10V4m8 16v-7M2 20h20',evidence:'M3 4h7l2 2l2-2h7v16h-7l-2 2l-2-2H3V4m9 2v16',settings:'M12 8a4 4 0 1 0 0 8a4 4 0 1 0 0-8M9 3h6l1 3l3 1l2 5l-2 5l-3 1l-1 3H9l-1-3l-3-1l-2-5l2-5l3-1z',plus:'M12 5v14M5 12h14',close:'M6 6l12 12M18 6L6 18',menu:'M4 6h16M4 12h16M4 18h16',moon:'M20 14A8 8 0 0 1 10 4a8 8 0 1 0 10 10',sun:'M12 8a4 4 0 1 0 0 8a4 4 0 1 0 0-8M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12l1 1M5 19l1-1M18 6l1-1',weight:'M6 8h12l3 13H3L6 8m3 0V6a3 3 0 0 1 6 0v2',check:'M5 12l4 4L19 6',time:'M12 8v4l3 2M12 3a9 9 0 1 0 0 18a9 9 0 1 0 0-18',download:'M12 3v12m-5-5l5 5l5-5M4 17v4h16v-4',lock:'M7 10V7a5 5 0 0 1 10 0v3M5 10h14v11H5z',search:'M10 3a7 7 0 1 0 0 14a7 7 0 1 0 0-14m5 12l6 6'};
export const icon=n=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[n]||paths.check}" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
export const btn=(label,action,cls='',ico='')=>`<button class="btn ${cls}" data-action="${esc(action)}">${ico?icon(ico):''}${esc(label)}</button>`;
export const empty=(title,description,action='',label='')=>`<div class="empty"><strong>${esc(title)}</strong><p>${esc(description)}</p>${action?btn(label,action,'small'):''}</div>`;
export const field=(name,label,value='',type='text',attrs='',help='')=>{const original=typeof value==='number'?String(value):null,display=type==='number'&&Number.isFinite(value)?String(Number(value.toFixed(2))):value;return `<div class="field"><label for="f-${name}">${esc(label)}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(display??'')}" ${type==='number'&&original!==null?'data-original-number="'+original+'"':''} ${help?'aria-describedby="help-'+name+'"':''} ${type==='number'?'inputmode="decimal"':''} ${attrs}>${help?'<small id="help-'+name+'">'+esc(help)+'</small>':''}</div>`};
export function formData(form){const data=new FormData(form);form.querySelectorAll('[data-original-number]').forEach(input=>{if(input.value===input.defaultValue)data.set(input.name,input.dataset.originalNumber)});return data}
export const select=(name,label,value,options,help='')=>`<div class="field"><label for="f-${name}">${esc(label)}</label><select id="f-${name}" name="${name}">${options.map(o=>`<option value="${esc(Array.isArray(o)?o[0]:o)}" ${value===(Array.isArray(o)?o[0]:o)?'selected':''}>${esc(Array.isArray(o)?o[1]:o)}</option>`).join('')}</select>${help?`<small>${help}</small>`:''}</div>`;
export const num=(v,d=0)=>Number.isFinite(Number(v))&&v!==null&&v!==''?Number(v).toLocaleString(undefined,{maximumFractionDigits:d}):'—';
export const dateLabel=(s,options={month:'short',day:'numeric'})=>new Date(s+'T12:00:00').toLocaleDateString(undefined,options);
export const metric=(title,value,unit,foot,ico)=>`<div class="card metric"><div class="metric-title">${esc(title)}${icon(ico)}</div><div class="metric-value mono">${value}<span>${esc(unit)}</span></div><div class="metric-foot">${esc(foot)}</div></div>`;
export function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),4000)}
export function modal(title,body,onSubmit){const d=document.querySelector('#modal'),trigger=document.activeElement,action=trigger?.closest('[data-action]')?.dataset.action;d.setAttribute('aria-labelledby','modal-title');d.innerHTML=`<div class="modal-header"><h2 id="modal-title">${esc(title)}</h2><button type="button" class="btn ghost small" data-close aria-label="Close dialog">${icon('close')}</button></div><form class="modal-body">${body}<p class="error" role="alert"></p><div class="modal-footer"><button type="button" class="btn" data-close>Cancel</button><button class="btn primary" type="submit">Save</button></div></form>`;d.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>d.close());d.onclose=()=>{const target=trigger?.isConnected?trigger:action?document.querySelector('[data-action="'+CSS.escape(action)+'"]'):null;(target||document.querySelector('#main'))?.focus({preventScroll:true})};d.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{await onSubmit(formData(e.target),e.target);d.close()}catch(err){d.querySelector('.error').textContent=err.message}finally{b.disabled=false}};if(!d.open)d.showModal();queueMicrotask(()=>{const target=d.querySelector('[name="kcal"],[name="weight"]')||d.querySelector('input:not([type="date"]):not([type="checkbox"]):not([type="file"]),select,textarea')||d.querySelector('[data-close]');target?.focus({preventScroll:true});if(target?.type==='number'||target?.type==='text')target.select()});return d}
let chartId=0;
export function chart(input,{unit='',secondary=null,height=230,color=null,bars=false,seriesLabel='Trend',secondaryLabel='Raw reading'}={}){
  const points=input.filter(p=>Number.isFinite(p.value)).sort((a,b)=>a.date.localeCompare(b.date));
  if(!points.length)return empty('Your trend starts here','Log a few entries to see how your progress changes over time.');
  const second=(secondary||[]).filter(p=>Number.isFinite(p.value)).sort((a,b)=>a.date.localeCompare(b.date));
  const id='chart-'+(++chartId),w=640,h=height,p={l:52,r:20,t:20,b:36},all=[...points,...second],values=all.map(x=>x.value);
  let lo=Math.min(...values),hi=Math.max(...values);if(bars)lo=0;const span=hi-lo||Math.max(1,Math.abs(hi)*.02);lo=bars?0:lo-span*.15;hi+=span*.15;
  const dates=all.map(x=>Date.parse(x.date+'T12:00:00Z')),first=Math.min(...dates),last=Math.max(...dates);
  const xx=date=>first===last?(p.l+w-p.r)/2:p.l+(Date.parse(date+'T12:00:00Z')-first)*(w-p.l-p.r)/(last-first),yy=value=>h-p.b-(value-lo)/(hi-lo)*(h-p.t-p.b);
  const path=arr=>arr.map((v,i)=>(i?'L':'M')+xx(v.date)+','+yy(v.value)).join(' '),ticks=Array.from({length:4},(_,i)=>lo+(hi-lo)*i/3),status=x=>x.complete===true?'Complete':x.complete===false?'Partial':'';
  const tip=x=>x.date+': '+num(x.value,2)+' '+unit+(status(x)?' · '+status(x):'');
  const mark=x=>bars?'<rect class="bar '+(x.complete===false?'partial':'')+'" x="'+(xx(x.date)-Math.min(8,180/points.length))+'" y="'+yy(x.value)+'" width="'+Math.min(16,360/points.length)+'" height="'+(h-p.b-yy(x.value))+'" tabindex="0" data-chart-tip="'+esc(tip(x))+'"><title>'+esc(tip(x))+'</title></rect>':'<circle class="point" cx="'+xx(x.date)+'" cy="'+yy(x.value)+'" r="3.5" tabindex="0" data-chart-tip="'+esc(tip(x))+'"><title>'+esc(tip(x))+'</title></circle>';
  const tableRows=[...points,...second.filter(x=>!points.some(p=>p.date===x.date)).map(x=>({date:x.date,value:null}))].sort((a,b)=>a.date.localeCompare(b.date));
  const legend=second.length?'<div class="chart-legend"><span><i class="swatch"></i>'+esc(seriesLabel)+'</span><span><i class="swatch raw"></i>'+esc(secondaryLabel)+'</span></div>':points.some(x=>x.complete!==undefined)?'<div class="chart-legend"><span><i class="swatch"></i>Complete day</span><span><i class="swatch partial"></i>Partial log</span></div>':'';
  return '<div class="chart-block">'+legend+'<svg viewBox="0 0 '+w+' '+h+'" class="chart" role="img" aria-labelledby="'+id+'-title '+id+'-desc"><title id="'+id+'-title">'+esc(unit)+' history</title><desc id="'+id+'-desc">'+esc(seriesLabel)+(second.length?' and '+esc(secondaryLabel):'')+' from '+points[0].date+' to '+points.at(-1).date+'. Focus a point or inspect the data table.</desc>'+ticks.map(v=>'<path class="gridline" d="M'+p.l+' '+yy(v)+'H'+(w-p.r)+'"/><text x="'+(p.l-8)+'" y="'+(yy(v)+4)+'" text-anchor="end">'+num(v,1)+'</text>').join('')+(second.length?'<path class="secondary" d="'+path(second)+'"/>':'')+(!bars?'<path class="line" '+(color?'style="stroke:'+color+'"':'')+' d="'+path(points)+'"/>':'')+points.map(mark).join('')+'<text x="'+p.l+'" y="'+(h-5)+'">'+dateLabel(points[0].date)+'</text>'+(first!==last?'<text x="'+(w-p.r)+'" y="'+(h-5)+'" text-anchor="end">'+dateLabel(points.at(-1).date)+'</text>':'')+'</svg><div class="chart-readout" aria-live="polite">Hover or focus a point to inspect it.</div><details class="chart-details"><summary>Inspect chart data</summary><div class="table-wrap"><table class="data-table"><caption class="sr-only">'+esc(unit)+' observations</caption><thead><tr><th>Date</th><th>'+esc(seriesLabel)+' · '+esc(unit||'Value')+'</th>'+(second.length?'<th>'+esc(secondaryLabel)+'</th>':'')+(points.some(x=>x.complete!==undefined)?'<th>Day status</th>':'')+'</tr></thead><tbody>'+tableRows.map(x=>'<tr><td>'+x.date+'</td><td>'+num(x.value,2)+'</td>'+(second.length?'<td>'+num(second.find(y=>y.date===x.date)?.value,2)+'</td>':'')+(points.some(y=>y.complete!==undefined)?'<td>'+status(x)+'</td>':'')+'</tr>').join('')+'</tbody></table></div></details></div>';
}
if(typeof document!=='undefined'){const inspect=e=>{const point=e.target.closest?.('[data-chart-tip]');if(point){const readout=point.closest('.chart-block').querySelector('.chart-readout');readout.textContent=point.dataset.chartTip;readout.classList.add('active')}};document.addEventListener('pointerover',inspect);document.addEventListener('focusin',inspect)}
